def sha256(path):
    return hashlib.sha256(path.read_bytes()).hexdigest()

def replace_one(text, pattern, replacement, label, flags=0):
    out, n = re.subn(pattern, replacement, text, count=1, flags=flags)
    if n != 1:
        raise SystemExit(f"{label}: expected 1 match, got {n}")
    return out

def replace_optional(text, pattern, replacement, label, flags=0):
    out, n = re.subn(pattern, replacement, text, count=1, flags=flags)
    if n > 1:
        raise SystemExit(f"{label}: expected <=1 match, got {n}")
    return out

def sync_truth(build, parent, release, status, note):
    stamp = datetime.now(timezone.utc).replace(microsecond=0).isoformat().replace("+00:00","Z")

    p = ROOT / "app.js"
    s = p.read_text(encoding="utf-8")
    s = replace_one(s, r'(?m)^const ATLAS_BUILD = "40\.4\.\d+";', f'const ATLAS_BUILD = "{build}";', "ATLAS_BUILD")
    s = replace_optional(s, r'(?m)^const ATLAS_ASSET_TOKEN = "market-core-v2\.0-alpha-build-40\.4\.\d+";', f'const ATLAS_ASSET_TOKEN = "market-core-v2.0-alpha-build-{build}";', "ATLAS_ASSET_TOKEN")
    p.write_text(s, encoding="utf-8")

    p = ROOT / "js/app.js"
    s = p.read_text(encoding="utf-8")
    s = replace_one(s, r'(?m)^\s*const ADMIN_BUILD = "40\.4\.\d+";', f'  const ADMIN_BUILD = "{build}";', "ADMIN_BUILD")
    s = replace_one(s, r'(?m)^\s*const ADMIN_RELEASE = ".*?";', f'  const ADMIN_RELEASE = "{release}";', "ADMIN_RELEASE")
    p.write_text(s, encoding="utf-8")

    p = ROOT / "js/market-stack.js"
    s = p.read_text(encoding="utf-8")
    s = replace_one(s, r'(?m)^\s*const BUILD = "40\.4\.\d+";', f'  const BUILD = "{build}";', "market-stack BUILD")
    p.write_text(s, encoding="utf-8")

    p = ROOT / "index.html"
    s = p.read_text(encoding="utf-8")
    s = replace_one(s, r'<meta name="atlas-build" content="40\.4\.\d+" />', f'<meta name="atlas-build" content="{build}" />', "index atlas build")
    s = replace_one(s, r'<meta name="administrator-build" content="40\.4\.\d+" />', f'<meta name="administrator-build" content="{build}" />', "index admin build")
    s = replace_one(s, r'<meta name="administrator-release" content="[^"]+" />', f'<meta name="administrator-release" content="{release}" />', "index release")
    s = replace_one(s, r'<meta name="atlas-asset-token" content="market-core-v2\.0-alpha-build-40\.4\.\d+" />', f'<meta name="atlas-asset-token" content="market-core-v2.0-alpha-build-{build}" />', "index asset token")
    s = replace_one(s, r'<title>Agent-Crypto @erith\.IA — Build 40\.4\.\d+ · Administrator</title>', f'<title>Agent-Crypto @erith.IA — Build {build} · Administrator</title>', "index title")
    s = re.sub(r'administrator-build-40\.4\.\d+', f'administrator-build-{build}', s)
    s = re.sub(r'Agent-Crypto @erith\.IA · Market Core · Build 40\.4\.\d+ · Version : Parker Lewis Can\'t Lose', f"Agent-Crypto @erith.IA · Market Core · Build {build} · Version : Parker Lewis Can't Lose", s)
    p.write_text(s, encoding="utf-8")

    ap = ROOT / "administrator-version.json"
    av = json.loads(ap.read_text(encoding="utf-8"))
    av["build"] = build
    av["global_versioning"] = build
    if "administrator_build" in av: av["administrator_build"] = build
    if "primary_build" in av: av["primary_build"] = build
    if "build_label" in av: av["build_label"] = f"Build {build}"
    if "asset_token" in av: av["asset_token"] = f"market-core-v2.0-alpha-build-{build}"
    av["release"] = release
    av["status"] = status
    av["prepared_at"] = stamp
    av["published_at"] = stamp
    if "timestamp" in av: av["timestamp"] = stamp
    if "parent_build" in av: av["parent_build"] = parent
    av.setdefault("depth_contract", {})
    av["depth_contract"].update({
        "geometry_master": "40.4.189",
        "shared_shell": True,
        "indices_depth": int(build.rsplit(".",1)[1]) >= 190,
        "energy_depth": int(build.rsplit(".",1)[1]) >= 191,
        "cross_market_depth": int(build.rsplit(".",1)[1]) >= 192,
        "harmonized": int(build.rsplit(".",1)[1]) >= 193,
        "source_truth_only": True,
        "orders_allowed": False,
        "new_timer": False,
        "new_observer": False
    })
    ap.write_text(json.dumps(av, ensure_ascii=False, indent=2) + "\n", encoding="utf-8")

    vp = ROOT / "version.json"
    v = json.loads(vp.read_text(encoding="utf-8"))
    v.update(release=release, build=build, asset_token=f"market-core-v2.0-alpha-build-{build}", status=status, prepared_at=stamp, published_at=stamp, parent_build=parent)
    if note not in v.get("lineage",""):
        v["lineage"] = v.get("lineage","") + " → " + note
    v.setdefault("contracts", {})
    v["contracts"]["parallel_market_depth"] = {
        "geometry_master": "40.4.189",
        "indices_depth": int(build.rsplit(".",1)[1]) >= 190,
        "energy_depth": int(build.rsplit(".",1)[1]) >= 191,
        "cross_market_depth": int(build.rsplit(".",1)[1]) >= 192,
        "harmonized": int(build.rsplit(".",1)[1]) >= 193,
        "asset_selection": True,
        "multi_horizon": True,
        "math_core_historical": True,
        "source_truth_only": True,
        "orders_allowed": False
    }
    files = v.setdefault("files", {})
    owners = (
        "index.html","app.js","js/app.js","js/market-stack.js",
        "js/parallel-markets.js","parallel-markets.css","administrator-version.json"
    )
    for rel in owners:
        if rel in files or (ROOT / rel).exists():
            files[rel] = sha256(ROOT / rel)
    vp.write_text(json.dumps(v, ensure_ascii=False, indent=2) + "\n", encoding="utf-8")

def apply(stage):
    if stage not in STAGES:
        raise SystemExit(f"Unsupported stage {stage}")
    build,parent,release,status,note = STAGES[stage]

    target = JS_TEMPLATE.replace("__BUILD__", build).replace("__DEPTH_LEVEL__", str(stage))
    (ROOT / "js/parallel-markets.js").write_text(target, encoding="utf-8")

    cp = ROOT / "parallel-markets.css"
    css = cp.read_text(encoding="utf-8")
    marker = "40.4.190+ — PARALLEL MARKET DEPTH"
    if marker not in css:
        css += CSS_APPEND
        cp.write_text(css, encoding="utf-8")

    sync_truth(build,parent,release,status,note)

    assert f'const BUILD = "{build}";' in (ROOT/"js/parallel-markets.js").read_text(encoding="utf-8")
    assert f"const DEPTH_LEVEL = {stage};" in (ROOT/"js/parallel-markets.js").read_text(encoding="utf-8")
    assert json.loads((ROOT/"version.json").read_text(encoding="utf-8"))["build"] == build
    assert json.loads((ROOT/"administrator-version.json").read_text(encoding="utf-8"))["build"] == build
    assert "38.15.11" in (ROOT/"index.html").read_text(encoding="utf-8")
    print(f"Agent-Crypto {build} depth stage PASS")

if __name__ == "__main__":
    parser=argparse.ArgumentParser()
    parser.add_argument("--stage", type=int, required=True)
    args=parser.parse_args()
    apply(args.stage)
